    function decorateMarkdownHighlights(html2) {
      if (typeof document === "undefined") return String(html2 || "");
      const tpl = document.createElement("template");
      tpl.innerHTML = toTrustedHTML(String(html2 || ""));
      const walker = document.createTreeWalker(tpl.content, NodeFilter.SHOW_TEXT);
      const nodes2 = [];
      while (walker.nextNode()) {
        if (walker.currentNode instanceof Text) nodes2.push(walker.currentNode);
      }
      for (const node2 of nodes2) {
        const parent = node2.parentElement;
        if (!parent) continue;
        if (parent.closest(
          "pre, code, kbd, samp, a, .katex, .katex-html, .katex-mathml, .bsb-katex-display, .bsb-katex-inline, .bsb-math-fallback, .mermaid, .bsb-md-highlight, script, style"
        )) {
          continue;
        }
        const text2 = node2.nodeValue || "";
        if (!text2.includes("==")) continue;
        const regex2 = /==([^=\n]{1,120}?)==/g;
        let match2;
        let cursor = 0;
        let changed = false;
        const frag = document.createDocumentFragment();
        while (match2 = regex2.exec(text2)) {
          changed = true;
          if (match2.index > cursor) {
            frag.appendChild(document.createTextNode(text2.slice(cursor, match2.index)));
          }
          const value2 = String(match2[1] || "").trim();
          if (!value2) {
            frag.appendChild(document.createTextNode(match2[0]));
            cursor = regex2.lastIndex;
            continue;
          }
          let hash = 0;
          for (let i2 = 0; i2 < value2.length; i2 += 1) {
            hash = hash * 31 + value2.charCodeAt(i2) >>> 0;
          }
          const tone = hash % 4;
          const mark = document.createElement("mark");
          mark.className = `bsb-md-highlight bsb-md-highlight-${tone}`;
          mark.textContent = value2;
          frag.appendChild(mark);
          cursor = regex2.lastIndex;
        }
        if (!changed) continue;
        if (cursor < text2.length) {
          frag.appendChild(document.createTextNode(text2.slice(cursor)));
        }
        node2.replaceWith(frag);
      }
      return tpl.innerHTML;
    }
    function knowledgeAnswerReadingBlocks(text2) {
      const codes = [];
      let source = String(text2 || "").replace(/\r\n?/g, "\n").trim();
      if (!source) return [];
      source = source.replace(/```[\s\S]*?```/g, (m2) => {
        const i2 = codes.length;
        codes.push(m2);
        return `@@BSBSPLITCODE${i2}@@`;
      });
      const restore2 = (chunk) => String(chunk || "").replace(/@@BSBSPLITCODE(\d+)@@/g, (_2, id38) => {
        const i2 = Number(id38);
        return codes[i2] != null ? codes[i2] : "";
      });
      const blocks2 = [];
      let paragraph = [];
      let topic = "";
      const flush = () => {
        const value2 = paragraph.join("\n").trim();
        paragraph = [];
        if (!value2) return;
        blocks2.push({ type: "paragraph", text: restore2(value2), topic });
      };
      for (const rawLine of source.split("\n")) {
        const line2 = rawLine.trimEnd();
        const trimmed = line2.trim();
        if (!trimmed) {
          flush();
          continue;
        }
        if (/^@@BSBMATH\d+@@$/.test(trimmed)) {
          flush();
          blocks2.push({ type: "paragraph", text: restore2(trimmed), topic });
          continue;
        }
        const heading = trimmed.match(/^#{1,4}\s+(.+)$/);
        if (heading) {
          flush();
          topic = (heading[1] || "").replace(/[*_`]+/g, "").trim();
          blocks2.push({ type: "heading", text: topic });
          continue;
        }
        if (/^(-{3,}|\*{3,}|_{3,})$/.test(trimmed)) {
          flush();
          continue;
        }
        paragraph.push(line2);
      }
      flush();
      return blocks2;
    }
